 if(awp_option('archives_style_border') == 'true'){                   $css_text .= ".awp_archive_widget { border:".awp_option('archives_style_border_width').' '.awp_option('archives_style_border_style').' '.awp_option('archives_style_border_color')." !important }
";             $css_text .= awp_option('archives_style_border_radius') == 'round' ? '.awp_archive_widget { -moz-border-radius:5px; -webkit-border-radius:5px; border-radius:5px }' : ''.''." 
";         }             $css_text .= ".awp_archives_colour { color:".awp_option('awp_archives_dropdown_inst_colour')." !important }
";               /**          * Filter the unprocessed CSS array          */         $css_text = apply_filters('advanced_widget_pack_css', $css_text);              header("Content-type: text/css");         echo $css_text;         exit();     }      This above function also works fine. It outputs a CSS file.

